"""
OpenAI-compatible API (``/api/v1/...``) backed by codx-junior profiles.

This is the public face of :mod:`codx.junior.openai_api`:

* ``GET  /api/v1/models``                          - the profiles of the PAT
* ``GET  /api/v1/models/<model>``                  - one profile
* ``POST /api/v1/chat/completions``                - chat, ``model`` = profile
* ``POST /api/v1/completions``                     - legacy alias
* ``GET  /api/v1/conversations/<conversation_id>`` - recover a conversation

Authentication is an installation-wide **personal access token** sent as
``Authorization: Bearer <PAT>``; there is no user session involved and the token
declares which profiles (models) it may use. See
:mod:`codx.junior.security.api_tokens` and ``docs/openai-compatible-api.md``.

Client setup::

    OPENAI_BASE_URL=http://<codx-junior>/api
    OPENAI_API_KEY=cxj_pat_...
    model=<profile>

Made with ❤️ by codx-junior
"""

from __future__ import annotations

import json
import logging
from typing import Any, Dict

from fastapi import APIRouter, Request
from fastapi.responses import JSONResponse, StreamingResponse

from codx.junior import openai_api as service
from codx.junior.security.workspace_api import extract_auth_token

logger = logging.getLogger(__name__)

router = APIRouter()


def _error(
    status: int,
    message: str,
    code: str = "invalid_request_error",
    type: str = "invalid_request_error",
) -> JSONResponse:
    """Return an OpenAI-shaped error body so any client can surface it."""
    return JSONResponse(
        status_code=int(status),
        content={
            "error": {
                "message": str(message),
                "type": type,
                "param": None,
                "code": code,
            }
        },
    )


def bearer(request: Request) -> str:
    """Return the PAT of the request (``Authorization: Bearer`` or alias)."""
    token, _header = extract_auth_token(request)
    return token


def _handle_error(ex: service.OpenAIApiError) -> JSONResponse:
    if ex.status >= 500:
        logger.warning("OpenAI API: %s (%s)", ex.message, ex.code)
    return _error(ex.status, ex.message, ex.code, ex.type)


def _server_error(action: str, ex: Exception) -> JSONResponse:
    logger.exception("OpenAI API: %s failed", action)
    return _error(500, f"{action} failed: {ex}", "api_error", "api_error")


async def _body(request: Request) -> Any:
    return await request.json()


@router.get("/v1/models", tags=["openai"])
def list_models(request: Request):
    """List the profiles (models) the request's PAT can reach."""
    try:
        return service.list_models(bearer(request))
    except service.OpenAIApiError as ex:
        return _handle_error(ex)
    except Exception as ex:
        return _server_error("models", ex)


@router.get("/v1/models/{model_id:path}", tags=["openai"])
def retrieve_model(model_id: str, request: Request):
    """Return one model, i.e. one profile granted to the request's PAT."""
    try:
        models = service.list_models(bearer(request))["data"]
    except service.OpenAIApiError as ex:
        return _handle_error(ex)
    except Exception as ex:
        return _server_error("models", ex)
    for model in models:
        if model["id"] == model_id:
            return model
    return _error(
        404,
        f"Profile '{model_id}' is not available for this token. See GET /v1/models.",
        "model_not_found",
    )


def _stream(payload: Dict[str, Any]):
    """Emit an OpenAI SSE stream: one content delta, the stop chunk, [DONE]."""

    def chunk(delta: Dict[str, Any], finish_reason=None) -> str:
        data = {
            "id": payload.get("id"),
            "object": "chat.completion.chunk",
            "created": payload.get("created"),
            "model": payload.get("model"),
            "conversation_id": payload.get("conversation_id"),
            "choices": [
                {"index": 0, "delta": delta, "logprobs": None, "finish_reason": finish_reason}
            ],
        }
        return f"data: {json.dumps(data)}\n\n"

    yield chunk({"role": "assistant", "content": ""})
    yield chunk({"content": payload["choices"][0]["message"]["content"]})
    yield chunk({}, "stop")
    yield "data: [DONE]\n\n"


@router.post("/v1/chat/completions", tags=["openai"])
async def create_chat_completion(request: Request):
    """
    Serve one chat completion with the profile named in ``model``.

    ``conversation_id`` (optional) continues a previous conversation; the answer
    always carries the id, both in the body and in ``x-codx-conversation-id``.
    """
    token = bearer(request)
    try:
        body = await _body(request)
    except Exception:
        return _error(400, "Invalid JSON body", "invalid_request")
    try:
        payload = await service.chat_completion(token, body)
    except service.OpenAIApiError as ex:
        return _handle_error(ex)
    except Exception as ex:
        return _server_error("chat completion", ex)
    headers = {
        "x-codx-conversation-id": str(payload.get("conversation_id") or ""),
        "cache-control": "no-store",
    }
    if isinstance(body, dict) and body.get("stream"):
        return StreamingResponse(
            _stream(payload), media_type="text/event-stream", headers=headers
        )
    return JSONResponse(content=payload, headers=headers)


@router.post("/v1/completions", tags=["openai"])
async def create_completion(request: Request):
    """
    Legacy ``/v1/completions`` alias.

    ``prompt`` (string or list of strings) becomes the user message, so old
    clients keep working against the same PAT and profile routing.
    """
    try:
        body = await _body(request)
    except Exception:
        return _error(400, "Invalid JSON body", "invalid_request")
    if isinstance(body, dict) and "prompt" in body and not body.get("messages"):
        prompt = body.get("prompt")
        if isinstance(prompt, list):
            prompt = "\n".join(str(item) for item in prompt)
        body = {**body, "messages": [{"role": "user", "content": str(prompt or "")}]}
    try:
        payload = await service.chat_completion(bearer(request), body)
    except service.OpenAIApiError as ex:
        return _handle_error(ex)
    except Exception as ex:
        return _server_error("completion", ex)
    return JSONResponse(
        content=payload,
        headers={
            "x-codx-conversation-id": str(payload.get("conversation_id") or ""),
            "cache-control": "no-store",
        },
    )


@router.get("/v1/conversations/{conversation_id}", tags=["openai"])
def get_conversation(conversation_id: str, request: Request):
    """
    Recover a previous conversation: the stored transcript, in the shape of the
    OpenAI Conversations API (``object``, ``created_at``, ``metadata``, items)
    plus a plain ``messages`` list.
    """
    try:
        return service.get_conversation(bearer(request), conversation_id)
    except service.OpenAIApiError as ex:
        return _handle_error(ex)
    except Exception as ex:
        return _server_error("conversation", ex)


