import logging
from typing import Any, Dict, List, Optional

from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel, Field

from codx.junior.api import require_admin
from codx.junior.model.model import CodxUser
from codx.junior.security import api_tokens as token_store

logger = logging.getLogger(__name__)

router = APIRouter()


class ApiTokenCreate(BaseModel):
    """Payload of a new PAT."""

    name: str = Field(description="Human label of the token")
    profiles: List[str] = Field(
        default_factory=list,
        description=(
            "Profiles (models) the token may use: a profile name, "
            "'<project>/<profile>' or the profile's api_settings.model_name. "
            "Empty or ['*'] grants every profile exposed through the API."
        ),
    )
    description: str = Field(default="", description="Free text note")
    expires_at: Optional[str] = Field(
        default=None, description="Optional ISO-8601 UTC expiry"
    )


class ApiTokenUpdate(BaseModel):
    """Partial update of a PAT. Omitted fields are left untouched."""

    name: Optional[str] = None
    description: Optional[str] = None
    profiles: Optional[List[str]] = None
    enabled: Optional[bool] = None
    expires_at: Optional[str] = None


def _handle(action: str, ex: Exception) -> HTTPException:
    logger.warning("api_tokens: %s failed: %s", action, ex)
    if isinstance(ex, KeyError):
        return HTTPException(status_code=404, detail=str(ex).strip("'\""))
    return HTTPException(status_code=400, detail=str(ex))


