"""
Admin API for the installation-wide personal access tokens (PATs).

A PAT authenticates the OpenAI-compatible API (``/api/v1/...``): it is not tied
to a user and it declares which profiles (models) it can reach. The token
secret is shown exactly once, by ``POST /api/api-tokens``.

    GET    /api/api-tokens            - list the tokens (no secrets)
    GET    /api/api-tokens/profiles   - profiles that can be granted
    POST   /api/api-tokens            - create (secret returned once)
    PATCH  /api/api-tokens/{id}       - rename / re-grant profiles / disable
    DELETE /api/api-tokens/{id}       - revoke

Every endpoint requires an admin session. See
``docs/openai-compatible-api.md`` for the client setup.

Made with ❤️ by codx-junior
"""

from __future__ import annotations

import logging
from typing import Any, Dict, List, Optional

from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel, Field

from codx.junior.api import require_admin
from codx.junior.model.model import CodxUser
from codx.junior.security import api_tokens as token_store

logger = logging.getLogger(__name__)

router = APIRouter()


class ApiTokenCreate(BaseModel):
    """Payload of a new PAT."""

    name: str = Field(description="Human label of the token")
    profiles: List[str] = Field(
        default_factory=list,
        description=(
            "Profiles (models) the token may use: a profile name, "
            "'<project>/<profile>' or the profile's api_settings.model_name. "
            "Empty or ['*'] grants every profile exposed through the API."
        ),
    )
    description: str = Field(default="", description="Free text note")
    expires_at: Optional[str] = Field(
        default=None, description="Optional ISO-8601 UTC expiry"
    )


class ApiTokenUpdate(BaseModel):
    """Partial update of a PAT. Omitted fields are left untouched."""

    name: Optional[str] = None
    description: Optional[str] = None
    profiles: Optional[List[str]] = None
    enabled: Optional[bool] = None
    expires_at: Optional[str] = None


def _handle(action: str, ex: Exception) -> HTTPException:
    logger.warning("api_tokens: %s failed: %s", action, ex)
    if isinstance(ex, KeyError):
        return HTTPException(status_code=404, detail=str(ex).strip("'\""))
    return HTTPException(status_code=400, detail=str(ex))


@router.get("/api-tokens", tags=["api-tokens"])
def list_api_tokens(user: CodxUser = Depends(require_admin)):
    """List the installation PATs. Secrets and digests are never returned."""
    return {
        "object": "list",
        "data": [token_store.public_view(token) for token in token_store.list_tokens()],
    }


@router.get("/api-tokens/profiles", tags=["api-tokens"])
def list_grantable_profiles(user: CodxUser = Depends(require_admin)):
    """
    List the profiles that can be granted to a token.

    ``exposed`` tells whether the profile is already published through the API
    (``api_settings.active``); naming a profile in a token grants it even when
    it is not exposed.
    """
    from codx.junior.openai_api import profile_is_exposed, profile_model_id
    from codx.junior.profiles.profile_manager import ProfileManager
    from codx.junior.project.project_discover import find_all_projects

    data: List[Dict[str, Any]] = []
    for project in (find_all_projects() or {}).values():
        try:
            profiles = ProfileManager(settings=project).list_all_profiles()
        except Exception as ex:  # pragma: no cover - defensive
            logger.warning(
                "api_tokens: cannot list profiles of %s: %s",
                getattr(project, "project_name", "?"),
                ex,
            )
            continue
        for profile in profiles:
            data.append(
                {
                    "id": profile_model_id(project, profile),
                    "profile": str(getattr(profile, "name", "") or ""),
                    "project": str(getattr(project, "project_name", "") or ""),
                    "exposed": profile_is_exposed(profile),
                    "description": str(getattr(profile, "description", "") or ""),
                }
            )
    return {"object": "list", "data": data}


@router.post("/api-tokens", tags=["api-tokens"])
def create_api_token(
    payload: ApiTokenCreate, user: CodxUser = Depends(require_admin)
):
    """
    Create a PAT. The ``token`` field of the answer is the secret: it is shown
    once and cannot be recovered later.
    """
    try:
        token, secret = token_store.create_token(
            name=payload.name,
            profiles=payload.profiles,
            description=payload.description,
            expires_at=payload.expires_at,
        )
    except Exception as ex:
        raise _handle("create", ex)
    return {**token_store.public_view(token), "token": secret, "secret_once": True}


@router.patch("/api-tokens/{token_id}", tags=["api-tokens"])
def update_api_token(
    token_id: str, payload: ApiTokenUpdate, user: CodxUser = Depends(require_admin)
):
    """Rename, re-grant, disable or re-expire a PAT."""
    try:
        token = token_store.update_token(
            token_id, **payload.model_dump(exclude_unset=True)
        )
    except Exception as ex:
        raise _handle("update", ex)
    return token_store.public_view(token)


@router.delete("/api-tokens/{token_id}", tags=["api-tokens"])
def delete_api_token(token_id: str, user: CodxUser = Depends(require_admin)):
    """Revoke a PAT: it stops authenticating immediately."""
    if not token_store.delete_token(token_id):
        raise HTTPException(status_code=404, detail=f"Unknown api token: {token_id}")
    return {"id": token_id, "deleted": True}


